/**
 * Растровые иконки.
 *
 * iOS не берёт SVG для значка на домашнем экране — только PNG. Они
 * собраны из той же векторной иконки и лежат здесь, а не в файловой
 * системе: контейнер api не имеет тома со статикой, и любой файл
 * рядом с кодом пришлось бы класть в образ отдельным шагом сборки.
 */
/** Иконка 180×180 — из rozmovio-app-icon.svg, для домашнего экрана. */
export const APP_ICON_180 = Buffer.from(
  '',
  'base64',
);

