/**
 * Картинка для ссылки, 1200x630 (og:image).
 *
 * Когда ссылку на сайт кидают в мессенджер, соцсеть или чат, тот
 * тянет og:image и рисует карточку. Без неё в карточке пусто или
 * случайный кусок страницы — и ссылка выглядит как спам.
 *
 * Собрана из знака брендбука и заголовка страницы, лежит в коде по
 * той же причине, что и иконки выше: тома со статикой у контейнера
 * api нет.
 */
export const OG_IMAGE = Buffer.from(
  '',
  'base64',
);
